#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
SKIPPED=()        # things we couldn't do

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with env_set's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Usage: scripts/setup_wizard.sh [local|deploy|all]   (default: asks)
#   local  = stages 1-3: dedicated Hermes home (~/.hermes-intake, gateway on 127.0.0.1:8643),
#            model keys, OpenRouter privacy (enough to start the e2e)
#   deploy = stages 4-8: Slack, Supabase, GCP VM, Vercel, optional tunnel
# Values go into ./.env, updated in place: other keys are never touched, and key
# names match case-insensitively so existing lowercase names are reused. Secrets
# are read hidden and never printed.
#
# Assumed repo paths (written by ticket #5): app/agents/assets/hermes-config.yaml.template and
# app/agents/assets/client-intake/SKILL.md.

# The Intake service runs its OWN Hermes home and gateway, separate from any personal
# Hermes in ~/.hermes (HERMES_HOME selects the home: hermes_constants.get_hermes_home).
# This script never writes to, restarts or stops ~/.hermes or its hermes-gateway unit.
# INTAKE_HERMES_HOME (not HERMES_HOME) so a shell export for another Hermes is ignored.
INTAKE_HERMES_HOME="${INTAKE_HERMES_HOME:-$HOME/.hermes-intake}"
HERMES_HOME="$INTAKE_HERMES_HOME"
HERMES_ENV="$HERMES_HOME/.env"
HERMES_PORT="${INTAKE_HERMES_PORT:-8643}"
HERMES_UNIT="hermes-intake-gateway"
HERMES_UNIT_DIR="${XDG_CONFIG_HOME:-$HOME/.config}/systemd/user"
HERMES_TEMPLATE="app/agents/assets/hermes-config.yaml.template"
HERMES_SKILL_SRC="app/agents/assets/client-intake/SKILL.md"
HERMES_INSTALLER="https://hermes-agent.nousresearch.com/install.sh"

# ── Extra helpers (stage-level, not part of the library above) ────────────

# env_read FILE KEY: value of KEY in FILE (case-insensitive name), quotes removed.
env_read() {
  [[ -f "$1" ]] || return 1
  local line value sq="'\\''"
  line=$(grep -iE "^(export[[:space:]]+)?${2}=" "$1" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then value="${value:1:${#value}-2}"; fi
  [[ -n "$value" ]] || return 1
  printf '%s' "$value"
}

# env_set FILE KEY VALUE: replace KEY's line in place (case-insensitive; keeps the
# existing spelling, every other line, order and mode), or append KEY if absent.
env_set() {
  local file="$1" key="$2" value="$3" tmp sq="'\\''"
  [[ -e "$file" ]] || { mkdir -p "$(dirname "$file")"; (umask 077 && : > "$file"); }
  tmp=$(mktemp)
  KEY="$key" QVAL="'${value//\'/$sq}'" awk '
    BEGIN { k = tolower(ENVIRON["KEY"]); done = 0 }
    {
      line = $0; sub(/^export[ \t]+/, "", line)
      n = index(line, "=")
      name = (n > 0) ? substr(line, 1, n - 1) : ""
      if (n > 0 && tolower(name) == k) {
        if (!done) { print name "=" ENVIRON["QVAL"]; done = 1 }
        next
      }
      print
    }
    END { if (!done) print ENVIRON["KEY"] "=" ENVIRON["QVAL"] }
  ' "$file" > "$tmp"
  cat "$tmp" > "$file"
  rm -f "$tmp"
  chmod 600 "$file" 2>/dev/null || true
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$file"
  if [[ "$file" == "$ENV_FILE" ]]; then WRITTEN_ENV+=("$key"); fi
  return 0
}

# gen_key: 64 hex chars.
gen_key() { openssl rand -hex 32 2>/dev/null || head -c 32 /dev/urandom | od -An -tx1 | tr -d ' \n'; }

# http_status METHOD URL [TOKEN] [JSON_BODY]: prints the HTTP status; the response
# body lands in $HTTP_BODY_FILE. The token goes via a stdin curl config, never argv.
HTTP_BODY_FILE=$(mktemp)
trap 'rm -f "$HTTP_BODY_FILE"' EXIT
http_status() {
  local method="$1" url="$2" token="${3:-}" body="${4:-}"
  local args=(-sS -m 45 -o "$HTTP_BODY_FILE" -w '%{http_code}' -X "$method")
  if [[ -n "$body" ]]; then args+=(-H 'Content-Type: application/json' --data "$body"); fi
  if [[ -n "$token" ]]; then
    printf 'header = "Authorization: Bearer %s"\n' "$token" | curl -K - "${args[@]}" "$url" 2>/dev/null || printf '000'
  else
    curl "${args[@]}" "$url" 2>/dev/null || printf '000'
  fi
}

# smoke_chat NAME BASE_URL KEY MODEL: one tiny chat completion; success on HTTP 200.
smoke_chat() {
  local name="$1" base="$2" key="$3" model="$4" code msg
  code=$(http_status POST "${base%/}/chat/completions" "$key" \
    "{\"model\":\"$model\",\"max_tokens\":16,\"messages\":[{\"role\":\"user\",\"content\":\"Reply with: ok\"}]}")
  if [[ "$code" == "200" ]]; then
    printf '  %s✓%s %s answered (model %s)\n' "$GREEN" "$RESET" "$name" "$model"
    return 0
  fi
  msg=$(grep -oE '"message" *: *"[^"]{0,200}' "$HTTP_BODY_FILE" | head -n1 | sed 's/.*"//' || true)
  warn "$name smoke test failed: HTTP $code ${msg:+($msg)}"
  return 1
}

# provide_key ENVKEY "Label" URL "where to click": ensures the key is in .env and in
# Hermes's .env. Reuses an existing value (any name case); asks (hidden) otherwise.
provide_key() {
  local key="$1" label="$2" url="$3" where="$4" val existing upper
  upper=$(printf '%s' "$key" | tr '[:lower:]' '[:upper:]')
  existing=$(env_read "$ENV_FILE" "$key" || true)
  if [[ -n "$existing" ]]; then
    say "$label: found in $ENV_FILE (not shown)."
    val="$existing"
  else
    open_url "$url"
    step "$where"
    ask_secret val "Paste the $label:" || return 1
    [[ -n "$val" ]] || { warn "empty value; skipping $label"; return 1; }
    env_set "$ENV_FILE" "$key" "$val"
  fi
  env_set "$HERMES_ENV" "$upper" "$val"
}

# install_gateway_unit: write the user unit for the Intake gateway (own HERMES_HOME,
# own port from that home's .env) and (re)start it. Only touches $HERMES_UNIT.
install_gateway_unit() {
  local bin; bin=$(command -v hermes) || return 1
  say "Starting the Intake Hermes gateway ($HERMES_UNIT, user service)."
  mkdir -p "$HERMES_UNIT_DIR"
  cat > "$HERMES_UNIT_DIR/$HERMES_UNIT.service" <<UNIT
[Unit]
Description=Hermes Agent gateway for Intake (API server on 127.0.0.1:$HERMES_PORT)
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
WorkingDirectory=$HOME
Environment=PATH=$HOME/.local/bin:/usr/local/bin:/usr/bin:/bin
Environment=HERMES_HOME=$HERMES_HOME
ExecStart=$bin gateway run
Restart=always
RestartSec=5
KillMode=mixed
KillSignal=SIGTERM

[Install]
WantedBy=default.target
UNIT
  systemctl --user daemon-reload || return 1
  systemctl --user enable "$HERMES_UNIT.service" >/dev/null 2>&1 || true
  systemctl --user restart "$HERMES_UNIT.service"
}

add_hermes_path() { export PATH="$HOME/.local/bin:$PATH"; }

# ── Stages ────────────────────────────────────────────────────────────────

stage_hermes() {
  stage "Hermes: dedicated home, config, skill, API key"
  add_hermes_path
  if command -v hermes >/dev/null 2>&1; then
    say "Hermes is already installed ($(command -v hermes))."
  else
    say "Hermes is not installed. The official installer brings its own Python."
    say "Source: $HERMES_INSTALLER (install as your normal user, not root)."
    if confirm "Run the installer now (curl | bash --non-interactive)?"; then
      curl -fsSL "$HERMES_INSTALLER" | bash -s -- --non-interactive || warn "installer failed; fix and re-run"
      add_hermes_path
    else
      SKIPPED+=("Install Hermes: curl -fsSL $HERMES_INSTALLER | bash -s -- --non-interactive")
    fi
  fi
  if command -v hermes >/dev/null 2>&1; then
    if HERMES_HOME="$HERMES_HOME" hermes doctor >/dev/null 2>&1; then say "hermes doctor: ok"; else warn "hermes doctor reported problems; run: HERMES_HOME=$HERMES_HOME hermes doctor"; fi
  fi

  if [[ "$(realpath -m "$HERMES_HOME")" == "$(realpath -m "$HOME/.hermes")" ]]; then
    warn "$HERMES_HOME is your personal Hermes home; refusing to touch it."
    return 1
  fi
  mkdir -p "$HERMES_HOME/skills/client-intake"
  say "Dedicated Hermes home: $HERMES_HOME (your personal ~/.hermes is left alone)."
  if [[ -f "$HERMES_TEMPLATE" ]]; then
    if [[ -f "$HERMES_HOME/config.yaml" ]] && ! cmp -s "$HERMES_TEMPLATE" "$HERMES_HOME/config.yaml"; then
      cp "$HERMES_HOME/config.yaml" "$HERMES_HOME/config.yaml.bak.$(date +%s)"
      say "Old config.yaml backed up."
    fi
    cp "$HERMES_TEMPLATE" "$HERMES_HOME/config.yaml"
    say "config.yaml installed from $HERMES_TEMPLATE."
  else
    warn "$HERMES_TEMPLATE not found (ticket #5); merge that ticket first."
    SKIPPED+=("Install Hermes config template ($HERMES_TEMPLATE)")
  fi
  if [[ -f "$HERMES_SKILL_SRC" ]]; then
    cp "$HERMES_SKILL_SRC" "$HERMES_HOME/skills/client-intake/SKILL.md"
    say "client-intake skill installed."
  else
    warn "$HERMES_SKILL_SRC not found (ticket #5)."
    SKIPPED+=("Install the client-intake skill ($HERMES_SKILL_SRC)")
  fi

  # Generated secrets are reused on re-runs so the wizard stays idempotent.
  local hk ik
  hk=$(env_read "$HERMES_ENV" API_SERVER_KEY || env_read "$ENV_FILE" HERMES_API_KEY || gen_key)
  env_set "$HERMES_ENV" API_SERVER_ENABLED true
  env_set "$HERMES_ENV" API_SERVER_HOST 127.0.0.1
  env_set "$HERMES_ENV" API_SERVER_PORT "$HERMES_PORT"
  env_set "$HERMES_ENV" API_SERVER_KEY "$hk"
  env_set "$ENV_FILE" HERMES_API_KEY "$hk"
  env_set "$ENV_FILE" HERMES_ENABLED true
  env_set "$ENV_FILE" HERMES_BASE_URL "http://127.0.0.1:$HERMES_PORT"
  ik=$(env_read "$ENV_FILE" INTAKE_API_KEY || gen_key)
  env_set "$ENV_FILE" INTAKE_API_KEY "$ik"
  note "Keys were generated locally and are not displayed; read them from $ENV_FILE if needed."
  pause "Press Enter for the model keys"
}

stage_model_keys() {
  stage "Model keys, gateway start, smoke tests"
  add_hermes_path
  provide_key GROQ_API_KEY "Groq API key" "https://console.groq.com/keys" \
    "Create API Key, name it 'hermes-intake', copy it (shown once)." || true
  provide_key OPENROUTER_API_KEY "OpenRouter API key" "https://openrouter.ai/settings/keys" \
    "Create Key, copy it (shown once)." || true

  local i code="000" base key
  if command -v hermes >/dev/null 2>&1; then
    install_gateway_unit || warn "could not start $HERMES_UNIT; see: journalctl --user -u $HERMES_UNIT"
    note "On a headless VM also run: sudo loginctl enable-linger \$USER"
    base=$(env_read "$ENV_FILE" HERMES_BASE_URL || echo "http://127.0.0.1:$HERMES_PORT")
    key=$(env_read "$HERMES_ENV" API_SERVER_KEY || true)
    for i in $(seq 1 20); do
      code=$(http_status GET "${base%/}/health")
      [[ "$code" == "200" ]] && break
      sleep 1
    done
    if [[ "$code" == "200" ]]; then
      say "✓ Hermes /health is ok."
      code=$(http_status GET "${base%/}/v1/skills" "$key")
      if [[ "$code" == "200" ]] && grep -q 'client-intake' "$HTTP_BODY_FILE"; then
        say "✓ client-intake skill is visible to the gateway."
      else
        warn "skill check failed (HTTP $code); see: journalctl --user -u $HERMES_UNIT"
      fi
      code=$(http_status GET "${base%/}/v1/toolsets" "$key")
      if [[ "$code" != "200" ]]; then warn "toolset check returned HTTP $code"
      elif grep -qE '"enabled" *: *true' "$HTTP_BODY_FILE"; then warn "some toolsets are ENABLED; all must be disabled (check config.yaml)"
      else say "✓ all toolsets disabled."; fi
    else
      warn "Hermes /health did not answer within 20s"
      SKIPPED+=("Hermes gateway not healthy at $base")
    fi
  fi

  say "Smoke-testing each provider directly with your keys."
  local gm gb om ob
  gm=$(env_read "$ENV_FILE" GROQ_MODEL || echo openai/gpt-oss-120b)
  gb=$(env_read "$ENV_FILE" GROQ_BASE_URL || echo https://api.groq.com/openai/v1)
  om=$(env_read "$ENV_FILE" OPENROUTER_MODEL || echo nvidia/nemotron-3-super-120b-a12b:free)
  ob=$(env_read "$ENV_FILE" OPENROUTER_BASE_URL || echo https://openrouter.ai/api/v1)
  smoke_chat Groq "$gb" "$(env_read "$ENV_FILE" GROQ_API_KEY || true)" "$gm" || SKIPPED+=("Groq smoke test failed")
  smoke_chat OpenRouter "$ob" "$(env_read "$ENV_FILE" OPENROUTER_API_KEY || true)" "$om" \
    || note "If it says 'No endpoints found matching your data policy', the next stage fixes it."
  pause "Press Enter to continue"
}

stage_openrouter_privacy() {
  stage "OpenRouter: allow free-model endpoints"
  say "Free models are only served if your privacy settings allow them."
  open_url "https://openrouter.ai/settings/privacy"
  step "Enable the options that allow free model endpoints (the ones that may publish/train on prompts)."
  note "Wording changes over time; look for the toggle matching 'No endpoints found matching your data policy'."
  note "Transcripts are redacted before leaving the app, but treat this as a demo setting."
  step "Optional: buy \$10 of credits to lift the free-tier daily request cap (50/day)."
  open_url "https://openrouter.ai/settings/credits"
  pause "Press Enter to re-test OpenRouter"
  local om ob
  om=$(env_read "$ENV_FILE" OPENROUTER_MODEL || echo nvidia/nemotron-3-super-120b-a12b:free)
  ob=$(env_read "$ENV_FILE" OPENROUTER_BASE_URL || echo https://openrouter.ai/api/v1)
  smoke_chat OpenRouter "$ob" "$(env_read "$ENV_FILE" OPENROUTER_API_KEY || true)" "$om" \
    || SKIPPED+=("OpenRouter smoke test still failing (privacy setting or key)")
  say "Local setup done: the e2e can start now."
  pause "Press Enter to continue"
}

stage_slack() {
  stage "Slack app"
  open_url "https://api.slack.com/apps"
  step "Create New App → From scratch; pick your workspace."
  step "OAuth & Permissions → Bot Token Scopes → add chat:write. Install to Workspace."
  step "Copy the Bot User OAuth Token (starts xoxb-)."
  ask_secret SLACK_BOT_TOKEN "Paste the bot token:"
  step "Basic Information → App Credentials → Signing Secret → Show → copy."
  ask_secret SLACK_SIGNING_SECRET "Paste the signing secret:"
  step "In Slack, open the approval channel and run: /invite @<your app name>"
  step "Channel name → About tab → copy the Channel ID at the bottom (starts with C)."
  ask SLACK_CHANNEL_ID "Paste the channel ID:"
  env_set "$ENV_FILE" SLACK_BOT_TOKEN "$SLACK_BOT_TOKEN"
  env_set "$ENV_FILE" SLACK_SIGNING_SECRET "$SLACK_SIGNING_SECRET"
  env_set "$ENV_FILE" SLACK_CHANNEL_ID "$SLACK_CHANNEL_ID"
  note "The Interactivity URL is set in the VM stage, once the public host exists."
  pause "Press Enter to continue"
}

stage_supabase() {
  stage "Supabase (EU region)"
  open_url "https://supabase.com/dashboard/new"
  step "Create a project; choose an EU region (e.g. Frankfurt). Set and save a database password."
  step "Click Connect → connection string. Use port 5432 (Direct or Session pooler), never 6543."
  note "Direct connections can be IPv6-only; if your VM has no IPv6, use the Session pooler string."
  step "Replace [YOUR-PASSWORD] with your password and paste the whole string."
  local url=""
  while :; do
    ask_secret url "Paste the connection string:" || return 1
    if [[ "$url" == *":6543"* ]]; then warn "port 6543 is the transaction pooler; use 5432."; continue; fi
    [[ "$url" == postgres://* || "$url" == postgresql://* || "$url" == postgresql+asyncpg://* ]] && break
    warn "expected a postgresql:// URL"
  done
  env_set "$ENV_FILE" DATABASE_URL "postgresql+asyncpg://${url#*://}"
  pause "Press Enter to continue"
}

stage_vm() {
  stage "Google Cloud VM, Caddy, hostname"
  open_url "https://console.cloud.google.com/compute/instancesAdd"
  step "Machine: e2-medium. Region: an EU one (e.g. europe-west1). Boot disk: Debian/Ubuntu LTS."
  step "Add your SSH public key (Security → Manage access); use key login only."
  step "Firewall: allow tcp 22, 80, 443 only (tag the VM, e.g. 'intake')."
  note "gcloud compute firewall-rules create intake-web --allow tcp:22,tcp:80,tcp:443 --target-tags intake"
  ask VM_IP "VM external IP:"
  local def host
  def="${VM_IP//./-}.sslip.io"
  say "Hostname: sslip.io needs no signup (default); a DuckDNS name also works."
  ask PUBLIC_HOST "Public hostname, no https:// (Enter alone with no saved value uses $def):" || true
  host="${PUBLIC_HOST:-$def}"
  env_set "$ENV_FILE" PUBLIC_HOST "$host"
  say "On the VM, as the service user (unit and Caddyfile names are in the README Deploy section):"
  note "  sudo apt-get install -y docker.io docker-compose-plugin caddy git"
  note "  git clone <repo> && cd hermes_intake_agent && scripts/setup_wizard.sh local   # Hermes + skill on the VM"
  note "  copy your .env to the VM, then: chmod 600 .env"
  note "  Caddy site block: $host { reverse_proxy 127.0.0.1:8000 }; then enable the systemd units and Caddy"
  pause "Press Enter once https://$host/health answers"
  say "Now point Slack at the API."
  open_url "https://api.slack.com/apps"
  step "Your app → Interactivity & Shortcuts → On → Request URL: https://$host/slack/actions → Save."
  pause "Press Enter to continue"
}

stage_vercel() {
  stage "Vercel dashboard"
  open_url "https://vercel.com/new"
  step "Import the GitHub repo and set Root Directory to dashboard/."
  step "Add the API URL env var (VITE_API_URL unless dashboard/.env.example says otherwise) = https://$(env_read "$ENV_FILE" PUBLIC_HOST || echo '<your-host>')"
  step "Deploy, then copy the production URL (https://<name>.vercel.app)."
  local origin cors
  ask DASHBOARD_ORIGIN "Paste the dashboard origin:"
  origin="${DASHBOARD_ORIGIN%/}"
  cors=$(env_read "$ENV_FILE" CORS_ORIGINS || echo "http://localhost:5173")
  [[ ",$cors," == *",$origin,"* ]] || cors="$cors,$origin"
  env_set "$ENV_FILE" CORS_ORIGINS "$cors"
  note "Copy the updated .env to the VM and restart the API so CORS takes effect."
  pause "Press Enter to continue"
}

stage_tunnel() {
  stage "Optional: cloudflared quick-tunnel fallback"
  if ! confirm "Set up a laptop tunnel in case the VM stalls?"; then
    say "Skipped."
    return 0
  fi
  if ! command -v cloudflared >/dev/null 2>&1; then
    open_url "https://developers.cloudflare.com/cloudflare-one/connections/connect-networks/downloads/"
    step "Install cloudflared for your OS, then come back."
    pause "Press Enter when installed"
  fi
  if command -v cloudflared >/dev/null 2>&1; then
    say "When needed, run the API locally and: cloudflared tunnel --url http://127.0.0.1:8000"
    say "Then set Slack's Interactivity URL and the dashboard API URL to the printed trycloudflare.com host."
  else
    SKIPPED+=("cloudflared not installed (optional)")
  fi
  pause "Press Enter to finish"
}

run_wizard() {
  cd "$(dirname "${BASH_SOURCE[0]}")/.."
  local mode="${1:-}"
  if [[ -z "$mode" ]]; then
    say "Which part? local = Hermes + model keys (stages 1-3); deploy = Slack, Supabase, VM, Vercel, tunnel (4-8); all."
    read -r -p "  [local/deploy/all] " mode || mode=local
  fi
  case "$mode" in
    local)  TOTAL_STAGES=3 ;;
    deploy) TOTAL_STAGES=5 ;;
    all)    TOTAL_STAGES=8 ;;
    *) echo "usage: $0 [local|deploy|all]" >&2; return 2 ;;
  esac
  if [[ ! -f "$ENV_FILE" ]]; then
    if [[ -f .env.example ]]; then (umask 077 && cp .env.example "$ENV_FILE"); else (umask 077 && : > "$ENV_FILE"); fi
  fi
  chmod 600 "$ENV_FILE" 2>/dev/null || true

  banner "Hermes Intake setup ($mode)"
  if [[ "$mode" != deploy ]]; then stage_hermes; stage_model_keys; stage_openrouter_privacy; fi
  if [[ "$mode" != local ]]; then stage_slack; stage_supabase; stage_vm; stage_vercel; stage_tunnel; fi
  finish
}

run_wizard "$@"; exit
